import React, { useState, useEffect } from "react";
import axios from "axios";
import { useParams, useNavigate, useLocation } from "react-router-dom";
import "./App.css";
import Sidebar from "./Sidebar.js";
import "bootstrap/dist/css/bootstrap.min.css";
import { Dashboard as MoreVertIcon } from "@mui/icons-material";
import { Button } from "react-bootstrap";
import SearchIcon from "@mui/icons-material/Search";
import FavoriteIcon from "@mui/icons-material/Favorite";
import FavoriteBorderIcon from "@mui/icons-material/FavoriteBorder";
import { CartStorage } from "./CartStorage";
import ArrowBackIcon from "@mui/icons-material/ArrowBack";
import ImageCache from "./utils/ImageCache";
import Footer from "./Footer.js";
// import { appConfig } from "./config";

// const normalizeName = (s) =>
//   String(s || "")
//     .toLowerCase()
//     .replace(/\s+/g, " ")
//     .trim();

const getLimit = (product) => {
  if (!product) return Infinity;
  const apiLimit = Number(product.limit);
  if (Number.isFinite(apiLimit) && apiLimit > 0) {
    return apiLimit;
  }
  return Infinity;
};

const clampQtyFor = (product, qty) => {
  const n = Math.max(0, Number(qty) || 0);
  const limit = getLimit(product);
  const stock = Number(product?.stockLeft || 0);
  return Math.min(n, limit, stock);
};

const GroceryOfferItems = () => {
  const navigate = useNavigate();
  const { userType, userId, selectedUserType } = useParams();
  const [isMobile, setIsMobile] = useState(false);
  const [showMenu, setShowMenu] = useState(false);
  const [products, setProducts] = useState([]);
  const [imageUrls, setImageUrls] = useState({});
  const [imageLoading, setImageLoading] = useState(true);
  // const [showZoomModal, setShowZoomModal] = useState(false);
  // const [zoomImage, setZoomImage] = useState("");
  const [cart, setCart] = useState({});
  const [checked, setChecked] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const [likedProducts, setLikedProducts] = useState({});
  // const [zoomProduct, setZoomProduct] = useState(null);
  const [grandSummary, setGrandSummary] = useState({ items: 0, total: 0 });
  const location = useLocation();
  const mobileNumber = localStorage.getItem("customerMobileNumber");
  console.log("Mobile Number from localStorage:", mobileNumber);

  const getInitialCategory = () => {
    const encodedFromState = location?.state?.encodedCategory;
    if (encodedFromState) {
      try {
        return decodeURIComponent(encodedFromState);
      } catch {
        return encodedFromState;
      }
    }
    const stored = localStorage.getItem("encodedCategory");
    if (stored) {
      try {
        return decodeURIComponent(stored);
      } catch {
        return stored;
      }
    }
    return "Offers";
  };

  const [selectedCategory] = useState(getInitialCategory);

  useEffect(() => {
    console.log(imageLoading, checked, grandSummary);
  }, [imageLoading, checked, grandSummary]);

  // const MIN_ORDER_TOTAL =
  //   normalizeName(selectedCategory) === normalizeName("Unbeatable Offers")
  //     ? 100
  //     : 100;
  const OFFERS = "Offers";
  const encodedCategory = OFFERS;

  useEffect(() => {
    const saved = CartStorage.getAll() || [];
    const categories = Array.isArray(saved) ? saved : [saved];
    const exist = categories.find((c) => c.categoryName === selectedCategory);
    if (exist) {
      const restored = {};
      (exist.products || []).forEach((p) => {
        restored[String(p.productId)] = Number(p.qty);
      });
      setCart(restored);
    }
  }, [selectedCategory]);

  useEffect(() => {
    if (!selectedCategory) return;
    const current = Object.entries(cart).map(([productId, qty]) => {
      const product = products.find((p) => String(p.id) === String(productId));
      return {
        productId,
        productName: product?.name || "",
        qty: Number(qty),
        mrp: Number(product?.mrp || 0),
        discount: Number(product?.discount || 0),
        afterDiscountPrice: Number(product?.afterDiscount || 0),
        stockLeft: Number(product?.stockLeft || 0),
        image: product?.images?.[0] || "",
        code: product?.code || "",
        units: product?.units || "",
        limit: product?.limit || "",
      };
    });

    CartStorage.upsertCategory(selectedCategory, current);
    setGrandSummary(CartStorage.grandSummary());
  }, [cart, selectedCategory, products]);

  useEffect(() => {
    if (!products.length) return;

    setCart((prev) => {
      let changed = false;
      const next = { ...prev };
      for (const [pid, qty] of Object.entries(prev)) {
        const product = products.find((p) => String(p.id) === String(pid));
        if (!product) continue;
        const clamped = clampQtyFor(product, qty);
        if (clamped !== qty) {
          if (clamped <= 0) delete next[pid];
          else next[pid] = clamped;
          changed = true;
        }
      }
      return changed ? next : prev;
    });
  }, [products]);

  // const handleIncrement = (productId) =>
  //   setCart((prev) => {
  //     const product = products.find((p) => String(p.id) === String(productId));
  //     if (!product) return prev;
  //     const nextQty = clampQtyFor(product, (prev[productId] || 0) + 1);
  //     if (nextQty === prev[productId]) return prev;
  //     return { ...prev, [productId]: nextQty };
  //   });

  const handleAddClick = (id) => {
    const product = products.find((p) => String(p.id) === String(id));
    if (!product) return;
    const qty = clampQtyFor(product, 1);
    if (qty <= 0) return;
    setCart((prev) => ({ ...prev, [id]: qty }));
    setChecked(true);
  };

  // const getQty = (id) => Number(cart?.[id] || 0);
  // const canAddMore = (id) => {
  //   const product = products.find((p) => String(p.id) === String(id));
  //   if (!product) return false;
  //   const current = getQty(id);
  //   const maxAllowed = clampQtyFor(product, Infinity);
  //   return current < maxAllowed;
  // };

  const handleDecrementClick = (productId) =>
    setCart((prev) => {
      const next = (prev[productId] || 0) - 1;
      const copy = { ...prev };
      if (next <= 0) delete copy[productId];
      else copy[productId] = next;
      return copy;
    });

  useEffect(() => {
    localStorage.setItem("cartData", JSON.stringify(cart));
  }, [cart]);

  const toggleLike = (productId) => {
    setLikedProducts((prev) => ({
      ...prev,
      [productId]: !prev[productId],
    }));
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    handleResize();
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);

  // const handleImageClick = (imageSrc, product) => {
  //   setZoomImage(imageSrc);
  //   setZoomProduct(product);
  //   setShowZoomModal(true);
  // };

  function getItemTime(p) {
    if (p?.date) {
      const t = Date.parse(p.date);
      if (!Number.isNaN(t)) return t;
    }
    const candidates = [
      p.createdAt,
      p.created_on,
      p.createdDate,
      p.createDate,
      p.updatedAt,
      p.updated_on,
      p.modifiedAt,
      p.modified_on,
      p.addedDate,
      p.added_at,
      p.timestamp,
      p.timeStamp,
    ];
    for (const c of candidates) {
      const t = Date.parse(c);
      if (!Number.isNaN(t)) return t;
    }
    if (typeof p.id === "number") return p.id;
    const idNum = Number(String(p.id || "").replace(/\D/g, "")) || 0;
    return idNum;
  }

  useEffect(() => {
    if (!selectedCategory) return;     
    let cancelled = false;
    const controller = new AbortController();
    async function fetchProductsAndFirstImages(warm = false, signal) {
      try {
        if (!warm) setImageLoading(true);
        const url = `https://handymanapiv15-cmhuc3b9fcd0eeb9.canadacentral-01.azurewebsites.net/api/UploadGrocery/GetGroceryItemsBycategory?Category=${encodeURIComponent(
          selectedCategory,
        )}`;
        const { data: items } = await axios.get(url, { signal });
        const safeItems = Array.isArray(items) ? items : [];
        if (cancelled) return;
        const sorted = [...safeItems].sort((a, b) => {
          const stockA = Number(a.stockLeft || 0);
          const stockB = Number(b.stockLeft || 0);
          if (stockA <= 0 && stockB > 0) return 1;
          if (stockA > 0 && stockB <= 0) return -1;
          const timeA = getItemTime(a);
          const timeB = getItemTime(b);
          if (timeA !== timeB) return timeB - timeA;
          return String(b.id).localeCompare(String(a.id));
        });
        setProducts(sorted);
        if (warm) return;
        const firstImages = safeItems
          .map((p) => ({
            productId: p.id,
            photo: Array.isArray(p.images) ? p.images[0] : null,
          }))
          .filter((x) => !!x.photo);
        const cachedMap = {};
        const misses = [];
        for (const { productId, photo } of firstImages) {
          const blobUrl = ImageCache.getBlobUrl(photo);
          if (blobUrl) {
            cachedMap[productId] = [blobUrl];
            continue;
          }

          const cached = await ImageCache.getBase64(photo);
          if (cached) {
            const dataUrl = `data:image/jpeg;base64,${cached}`;
            ImageCache.setBlobUrl(photo, dataUrl); 
            cachedMap[productId] = [dataUrl];
          } else {
            misses.push({ productId, photo });
          }
        }
        if (Object.keys(cachedMap).length) {
          setImageUrls((prev) => ({ ...prev, ...cachedMap }));
        }
        if (cancelled) return;
        const fetchOne = async ({ productId, photo }) => {
          try {
            const res = await fetch(
              `https://handymanapiv15-cmhuc3b9fcd0eeb9.canadacentral-01.azurewebsites.net/api/FileUpload/download?generatedfilename=${encodeURIComponent(photo)}`,
              { signal },  
            );
            const json = await res.json();
            const b64 = json?.imageData || "";
            if (!b64) return;

            await ImageCache.setBase64(photo, b64);
            const dataUrl = `data:image/jpeg;base64,${b64}`;

            ImageCache.setBlobUrl(photo, dataUrl);

            if (!cancelled) {
              setImageUrls((prev) => {
                if (prev[productId]?.[0] === dataUrl) return prev;
                return { ...prev, [productId]: [dataUrl] };
              });
            }
          } catch (err) {
            console.error("fetchOne failed:", err); 
          }
        };
        await Promise.allSettled(misses.map(fetchOne));
      } catch (err) {
        if (err?.name !== "CanceledError" && err?.name !== "AbortError") {
          console.error("Error fetching grocery products:", err);
          if (!warm) {
            setProducts([]);
            setImageUrls({});
          }
        }
      } finally {
        if (!cancelled && !warm) setImageLoading(false);
      }
    }

    fetchProductsAndFirstImages(false, controller.signal);
 return () => {
      cancelled = true;
      controller.abort();
    };
  }, [selectedCategory]);         

  useEffect(() => {
    let savedCategories = [];
    try {
      const raw = localStorage.getItem("allCategories");
      if (raw) {
        const parsed = JSON.parse(raw);
        savedCategories = Array.isArray(parsed) ? parsed : [parsed];
      }
    } catch (e) {
      console.error("Invalid JSON in localStorage for allCategories:", e);
    }

    const currentCategory = decodeURIComponent(encodedCategory);
    const existingCategory = savedCategories.find(
      (c) => c.categoryName === currentCategory,
    );
    if (existingCategory) {
      const restoredCart = {};
      (existingCategory.products || []).forEach((p) => {
        restoredCart[p.productId] = p.qty;
      });
      setCart(restoredCart);
    }
  }, [encodedCategory]);

  return (
    <>
      <div>
        <div>
          <h1
            style={{
              background: "green",
              color: "white",
              fontFamily: "'Baloo 2'",
              fontSize: "25px",
              padding: "2px",
              fontWeight: "bold",
              textAlign: "center",
              width: "100%",
              boxShadow: "0 4px 15px rgba(0,0,0,0.2)",
              letterSpacing: "1px",
              marginBottom: "3px",
              position: "fixed",
              top: 0,
              left: 0,
              zIndex: 1000,
            }}
          >
            Lakshmi Mart
            <br />
            <span
              style={{
                fontSize: "12px",
                fontWeight: "bold",
                display: "block",
                marginTop: "2px",
                textAlign: "center",
                fontFamily: "Roboto",
              }}
            >
              FSSAI LIC Number - 20125051001066
            </span>
            <span
              style={{
                fontSize: "12px",
                fontWeight: "bold",
                display: "block",
                marginTop: "2px",
                textAlign: "center",
                fontFamily: "Roboto",
              }}
            >
              Delivery Timings : 07:00 AM -09:00 PM
            </span>
          </h1>
        </div>

        <div
          className="wrapper d-flex"
          style={{ marginTop: isMobile ? "65px" : "170px" }}
        >
          {!isMobile ? (
            <div className="ml-0 p-0 sde_mnu">
              <Sidebar userType={selectedUserType} />
            </div>
          ) : (
            <div className="groceryfloating-menu">
              <Button
                variant="primary"
                className="rounded-circle shadow"
                onClick={() => setShowMenu(!showMenu)}
              >
                <MoreVertIcon />
              </Button>
              {showMenu && (
                <div className="sidebar-container">
                  <Sidebar userType={selectedUserType} />
                </div>
              )}
            </div>
          )}

          <div className={`container ${isMobile ? "w-100" : "w-75"} `}>
            <div
              style={{
                position: "fixed",
                top: "65px",
                left: 0,
                width: "100%",
                background: "white",
                zIndex: 999,
                padding: "8px 12px",
                boxShadow: "0 2px 6px rgba(0,0,0,0.1)",
              }}
            >
              <div className="position-relative flex-grow-1 ms-5">
                <input
                  type="text"
                  className="form-control w-60 mt-2 ps-5 "
                  placeholder="Search Products"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value.trimStart())}
                />
                <SearchIcon
                  className="position-absolute top-50 start-0 translate-middle-y ms-3 text-muted"
                  style={{ pointerEvents: "none" }}
                />
              </div>

              {selectedCategory && (
                <>
                  <div className="d-flex align-items-center">
                    <ArrowBackIcon
                      className="me-2"
                      style={{ color: "green", cursor: "pointer" }}
                      onClick={() =>
                        navigate(`/profilePage/${userType}/${userId}`)
                      }
                    />
                    <h4 className="fw-bold mb-0">{selectedCategory}</h4>
                  </div>
                </>
              )}
            </div>

            {selectedCategory && (
              <>
                <div
                  className="d-flex justify-content-end"
                  style={{ marginTop: "90px" }}
                >
                  <span className="text-success text-xs">
                    Selected Qty:{" "}
                    <span className="text-danger fw-bold">
                      {Object.values(cart).reduce((sum, qty) => sum + qty, 0)}
                    </span>
                  </span>

                  <span className="text-success text-xs ms-2">
                    Total Price: Rs{" "}
                    <span className="text-danger fw-bold">
                      {Math.round(
                        Object.entries(cart).reduce((sum, [productId, qty]) => {
                          const product = products.find(
                            (p) => String(p.id) === String(productId),
                          );
                          return (
                            sum +
                            (product ? Number(product.afterDiscount) * qty : 0)
                          );
                        }, 0),
                      )}
                    </span>
                    /-
                  </span>
                </div>

                <div
                  className="grocery-row flex flex-wrap gap-1"
                  style={{ marginBottom: "60px" }}
                >
                  {products
                    .filter(
                      (p) =>
                        p.category?.toLowerCase() ===
                          selectedCategory.toLowerCase() &&
                        p.status === "Approved" &&
                        Number(p.discount) > 0 &&
                        (searchQuery === "" ||
                          p.name
                            ?.toLowerCase()
                            .includes(searchQuery.toLowerCase())),
                    )
                    .map((product) => {
                      const stock = Number(product.stockLeft || 0);
                      const isOutOfStock = stock <= 0;

                      return (
                        <div
                          key={product.id}
                          className="w-[200px] flex flex-col p-2 bg-white rounded shadow-sm border position-relative"
                          style={{
                            minHeight: "230px",
                            opacity: isOutOfStock ? 0.6 : 1,
                          }}
                        >
