                                  <div className="img-inner-ring" />
                                  <div className="img-center-dot" />
                                </div>
                              ) : (   
                              <img
                                src={imageUrls[product.id][0]}
                                alt={product.name}
                                style={{
                                  maxHeight: "80px",
                                  maxWidth: "100%",
                                  objectFit: "contain",
                                  cursor: isOutOfStock
                                    ? "not-allowed"
                                    : "pointer",
                                  borderRadius: "6px",
                                }}
                                onClick={() => {
                                  if (isOutOfStock) return;
                                  navigate(
                                    `/groceryComboOffer/${userType}/${userId}/${product.id}`,   
                                    {
                                      state: {
                                        product,                              
                                        imageUrl: imageUrls[product.id]?.[0] ?? null,  
                                      },
                                    }
                                  );
                                }}
                              />
                           )}

                            {isOutOfStock && (
                              <div
                                className="position-absolute d-flex justify-content-center align-items-center"
                                style={{
                                  top: 0,
                                  left: 0,
                                  width: "100%",
                                  height: "100%",
                                  background: "rgba(255,255,255,0.75)",
                                  borderRadius: "6px",
                                  zIndex: 2,
                                }}
                              >
                                <span
                                  style={{
                                    fontWeight: 500,
                                    backgroundColor: "grey",
                                    color: "white",
                                    fontSize: "10px",
                                    borderRadius: "6px",
                                    margin: "1px",
                                    padding: "2px",
                                  }}
                                >
                                  Out of Stock
                                </span>
                              </div>
                            )}
                          </div>

                          {/* Product Name */}   
                          <h6
                            className="text-start fw-bold m-0"
                            style={{
                              fontSize: "11px",
                              display: "-webkit-box",
                              WebkitLineClamp: 2,
                              WebkitBoxOrient: "vertical",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              lineHeight: "1.2em",
                              maxHeight: "3.6em",
                            }}
                          >
                            {product.name}
                          </h6>

                          {/* Price & Units & Max Limit (in stock only) */}
                          {!isOutOfStock && (
                            <div
                              className="text-start m-0"
                              style={{ fontSize: "11px" }}
                            >
                              {product.afterDiscount != null && (
                                <b className="text-success me-2">
                                  ₹{Math.round(Number(product.afterDiscount))}
                                </b>
                              )}
                              {product.mrp != null && (
                                <s className="text-muted">₹{product.mrp}</s>
                              )}
                              {product.units && (
                                <b
                                  className="text-success"
                                  style={{ marginLeft: "5px" }}
                                >
                                  {product.units}
                                </b>
                              )}
                          {/* <p className="blinking-icon mb-0" style={{color: "#db1818", fontSize: "9px", fontWeight: "bold"}}>Click on the image to see more</p> */}

                              {(() => {
                                const limit = getLimit(product);
                                return Number.isFinite(limit) && limit > 0 ? (
                                  <div
                                    style={{
                                      color: "#db1818",
                                      paddingBottom: "2px",
                                      fontSize: "10px",
                                      fontWeight: 600,
                                      marginBottom: "28px",
                                    }}
                                  >
                                    Max {limit} per customer
                                  </div>
                                ) : null;
                              })()}
                            </div>
                          )}

                          {/* Checkbox */}
                          {!isOutOfStock && (
                            <div
                              style={{
                                position: "absolute",
                                bottom: "8px",
                                left: "8px",
                              }}
                            >
                              <input
                                type="checkbox"
                                className="border-dark"
                                checked={cart[product.id] > 0}
                                onChange={() => {
                                  if (cart[product.id] > 0) {
                                    handleDecrementClick(product.id);
                                  } else {
                                    handleAddClick(product.id);
                                  }
                                }}
                              />   
                            </div>
                          )}

                       {/* Add / Counter */}
                        {!isOutOfStock && (
                          <div
                            style={{
                              position: "absolute",
                              bottom: "8px",
                              right: "8px",
                            }}
                          >
                            <button
                              className="btn fw-bold"
                              style={{
                                border: "1px solid green",
                                color: "white",
                                backgroundColor: "green",
                                borderRadius: "8px",
                                padding: "2px 8px",
                                fontSize: "11px",
                              }}
                              onClick={() => {
                                handleAddClick(product.id);
                                navigate(`/groceryComboOffer/${userType}/${userId}/${product.id}`, {
                                  state: {
                                    product,
                                    imageUrl: imageUrls[product.id]?.[0] ?? null,
                                  },
                                });
                              }}
                            >
                              ADD
                            </button>
                          </div>
                        )}
                        </div>
                      );
                    })}

                  {/* Cart Bar */}
                  {/* {(() => {
                    const readAllCategories = () => {
