                              }}
                            >
                              ₹{total}
                            </span>
                            {total < MIN_ORDER_TOTAL && (
                              <span
                                style={{
                                  fontSize: "13px",
                                  opacity: 0.9,
                                  fontWeight: "bold",
                                }}
                              >
                                Add ₹{MIN_ORDER_TOTAL - total} more to reach
